from decimal import Decimal
from typing import Any


def _value(record: dict, column: str) -> Any:
    value = record.get(column, "")
    return "" if value is None else value


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: Any,
    output_column: str,
) -> Any:
    if tables is None:
        return ""

    for row in tables.get(table_name, []):
        if _value(row, "DEL_FLG") == "Y":
            continue
        if _value(row, key_column) == key_value:
            return _value(row, output_column)

    return ""


def _failure(code: str, message: str) -> dict:
    return {
        "code": code,
        "message": message,
        "severity": "BLOCK",
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []
    old_record = {} if event == "INSERT" or old is None else old

    if table == "ORD_HEADER":
        # ORD-001
        if event in ("INSERT", "UPDATE"):
            discount = _number(_value(record, "DISC_PCT"))
            if not (discount >= Decimal("0") and discount <= Decimal("100")):
                errors.append(
                    _failure("E5001", "Discount out of range")
                )

        # ORD-002
        if event == "UPDATE":
            discount = _number(_value(record, "DISC_PCT"))
            owner_id = _value(record, "OWNER_UID")
            owner_role = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                owner_id,
                "ROLE_ID",
            )
            passes = not (
                discount > Decimal("20")
                and owner_role != "MGR"
                and owner_role != "ADMIN"
            )
            if not passes:
                errors.append(
                    _failure(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

        # ORD-003
        if event == "UPDATE":
            old_status = _value(old_record, "STAT_CD")
            status = _value(record, "STAT_CD")
            passes = not (
                old_status == "I"
                and status != "I"
                and status != "X"
            )
            if not passes:
                errors.append(
                    _failure(
                        "E5003",
                        "Invoiced order can only be cancelled",
                    )
                )

    elif table == "ORD_LINE":
        # ORD-004
        if event in ("INSERT", "UPDATE"):
            quantity = _number(_value(record, "QTY"))
            if not quantity > Decimal("0"):
                errors.append(
                    _failure("E5004", "Quantity must be positive")
                )

        # ORD-005
        if event == "INSERT":
            product_id = _value(record, "PROD_ID")
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                product_id,
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                errors.append(
                    _failure("E5005", "Product not active")
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
